package com.aistock.gateway.statistics;
import java.time.*;import java.util.concurrent.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class HttpStatisticsCollectorTest {
 static final Instant NOW=Instant.parse("2026-10-22T00:00:00Z");
 static HttpStatisticsCollector collector(Instant time){return new HttpStatisticsCollector(time,Clock.fixed(time,ZoneOffset.UTC));}
 @Test void aggregatesHttpErrorsAndMeanWithoutClaimingBusinessAccuracy(){var c=collector(NOW);for(int i=0;i<100;i++)c.record("MARKET",i<80?200:i<90?404:503,10_000_000);var g=c.snapshot(NOW).groups().stream().filter(x->x.group().equals("MARKET")).findFirst().orElseThrow();assertEquals("100",g.completedRequests());assertEquals("10",g.http4xx());assertEquals("10",g.http5xx());assertEquals("10.000",g.meanDurationMs());assertEquals("20.00",g.errorPercent());assertEquals("1000.000",g.totalDurationMs());}
 @Test void ignoresUnknownLabelsAndReportsDroppedOrEmptySamples(){var c=collector(NOW);for(int i=0;i<1000;i++)c.record("/private/user/"+i,200,1);c.drop();var s=c.snapshot(NOW);assertEquals(8,s.groups().size());assertEquals("1",s.droppedSamples());assertTrue(s.groups().stream().allMatch(g->g.completedRequests().equals("0")&&g.meanDurationMs()==null&&g.errorPercent()==null));}
 @Test void concurrentSnapshotsCannotContainMoreErrorsThanRequests()throws Exception{var c=collector(NOW);var pool=Executors.newFixedThreadPool(4);try{var futures=new java.util.ArrayList<Future<?>>();for(int n=0;n<3;n++)futures.add(pool.submit(()->{for(int i=0;i<1000;i++)c.record("USER",500,1_000_000);}));futures.add(pool.submit(()->{for(int i=0;i<1000;i++){var g=c.snapshot(NOW).groups().stream().filter(x->x.group().equals("USER")).findFirst().orElseThrow();assertTrue(Long.parseLong(g.http5xx())<=Long.parseLong(g.completedRequests()));}}));for(var f:futures)f.get();assertEquals("3000",c.snapshot(NOW).groups().get(0).completedRequests());}finally{pool.shutdownNow();}}
 @Test void processRestartStartsANewScope(){var a=collector(NOW);a.record("USER",200,1000);var b=collector(NOW.plusSeconds(10));assertNotEquals(a.snapshot(NOW).processStartedAt(),b.snapshot(NOW).processStartedAt());assertEquals("0",b.snapshot(NOW).groups().get(0).completedRequests());}
}
